// #a9a3cd (a3f8b6a65b89524a4da9a3cd) — меню «⋮» приглашения в /settings/users уходило за левый край на 1440 (−128 px).
// Проверка: на 1440 и других ширинах меню и каждый его пункт целиком в окне. Кейс BIZ-INV-009; связан #f0f6e2.
// Только чтение (меню открывается и закрывается Esc, пункты не нажимаются) → @prod-safe.
import * as path from 'path';
import { test, expect } from '@playwright/test';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#a9a3cd · #a3f8b6a65b89524a4da9a3cd';
const WIDTHS = [1920, 1440, 1366, 1280, 1024, 768, 720, 600, 480, 390];
const MENU_BUTTON = /^פעולות עבור ההזמנה של /;

test.describe(`Пользователи и приглашения — меню «⋮» приглашения в окне (${HASH})`, () => {
  for (const width of WIDTHS) {
    test(`ширина ${width}: меню каждого приглашения и все его пункты в пределах окна @desktop @prod-safe ${HASH}`, async ({ page }) => {
      await page.setViewportSize({ width, height: 900 });
      await page.goto('/settings/users');
      const buttons = page.getByRole('button', { name: MENU_BUTTON });
      await expect(buttons.first(), 'нет приглашений с меню «פעולות עבור ההזמנה של …» в testim').toBeVisible({ timeout: 30_000 });

      const count = await buttons.count();
      for (let i = 0; i < count; i++) {
        const button = buttons.nth(i);
        const label = (await button.getAttribute('aria-label')) || `#${i}`;
        await button.scrollIntoViewIfNeeded();
        await button.click();
        const menu = page.getByRole('menu');
        await expect(menu, `меню не открылось: ${label}`).toBeVisible();

        const m = await menu.evaluate((el) => {
          const r = el.getBoundingClientRect();
          const items = [...el.querySelectorAll('[role=menuitem],button')].map((it) => {
            const b = it.getBoundingClientRect();
            return { text: (it as HTMLElement).innerText.trim(), left: b.left, right: b.right };
          });
          return { left: r.left, right: r.right, vw: document.documentElement.clientWidth, items };
        });

        // Источник: «מה רצוי» #a9a3cd — меню целиком в экране (на 1440 было left = −128).
        expect(m.left, `${width}: ${label} — меню за левым краем`).toBeGreaterThanOrEqual(0);
        expect(m.right, `${width}: ${label} — меню за правым краем`).toBeLessThanOrEqual(m.vw);
        expect(m.items.length, `${width}: ${label} — в меню нет пунктов`).toBeGreaterThan(0);
        for (const it of m.items) {
          expect(it.left, `${width}: ${label} — пункт «${it.text}» за левым краем`).toBeGreaterThanOrEqual(0);
          expect(it.right, `${width}: ${label} — пункт «${it.text}» за правым краем`).toBeLessThanOrEqual(m.vw);
        }

        await page.keyboard.press('Escape');
        await expect(menu).toBeHidden();
      }
    });
  }
});
